import { initTRPC } from '@trpc/server';
import { createHTTPServer } from '@trpc/server/adapters/standalone';
import { z } from 'zod';

const t = initTRPC.create();

const appRouter = t.router({
  countdown: t.procedure.input(z.number()).subscription(async function* ({ input }) {
    for (let i = input; i >= 0; i--) {
      await new Promise((resolve) => setTimeout(resolve, 100));
      yield i;
    }
  }),
});

export type AppRouter = typeof appRouter;

const server = createHTTPServer({
  router: appRouter,
});

server.listen(3000);
console.log('tRPC server listening on http://localhost:3000');

import { createTRPCProxyClient, httpSubscriptionLink } from '@trpc/client';
import type { AppRouter } from './server';
import fs from 'node:fs';

async function main() {
  const logStream = fs.createWriteStream('/home/user/project/output.log', { flags: 'w' });

  const client = createTRPCProxyClient<AppRouter>({
    links: [
      httpSubscriptionLink({
        url: 'http://localhost:3000',
      }),
    ],
  });

  await new Promise<void>((resolve, reject) => {
    const subscription = client.countdown.subscribe(3, {
      onData(value) {
        console.log(value);
        logStream.write(`${value}\n`);
      },
      onError(error) {
        console.error(error);
        logStream.end();
        subscription.unsubscribe();
        reject(error);
      },
      onComplete() {
        logStream.end();
        subscription.unsubscribe();
        resolve();
      },
    });
  });
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

